  "error.systemFailure.connection": "कनेक्शन नहीं हो सका।",
  "error.systemFailure.other": "काम पूरा नहीं हो सका।",
  "error.unexpected.title": "अनचाही गड़बड़ी",
  "error.unexpected.prefilledReportGuidance": "यह ऐसा बग हो सकता है जिसे आप यहाँ ठीक नहीं कर सकते। {report} से इश्यू दर्ज करें और बताएँ कि किन कदमों के बाद समस्या आई।",
  "error.issue.report": "समस्या रिपोर्ट करें",
  "error.issue.openFailed": "ब्राउज़र में इश्यू पेज नहीं खुला, इसलिए उसका पता नीचे दिया गया है।",
