  "daemon.trust_directory_unreachable.recovery": "सिर्फ़ इस प्रोजेक्ट पर भरोसा करने के लिए फ़ोल्डर का विकल्प अनचेक करें, या वॉल्यूम के फिर जवाब देने पर दोबारा कोशिश करें।",
