  "daemon.queued_messages_dropped.recovery": "कुछ और भेजने से पहले सेशन की इनपुट लाइन जाँचें।",
  "daemon.queued_messages_dropped.details": "इनपुट लाइन में उस संदेश का हिस्सा हो सकता है जिसे ऐप पूरा नहीं लिख सका। सेशन में लिखा जाने वाला अगला संदेश उसी के साथ चलेगा।",
