  "daemon.draft_save_unconfirmed.summary": "{agent} ने इस सेशन के इनपुट बॉक्स का ड्राफ़्ट सेव करने की पुष्टि नहीं की, इसलिए {appName} ने अपना संदेश इनपुट बॉक्स में जैसा था वैसा ही लिख दिया।",
  "daemon.draft_save_unconfirmed.recovery": "बातचीत जाँचें: संदेश ड्राफ़्ट के साथ भेजा गया हो सकता है।",
  "daemon.draft_restore_unconfirmed.summary": "{appName} के संदेश भेजने के बाद {agent} ने ड्राफ़्ट इस सेशन के इनपुट बॉक्स में वापस रखने की पुष्टि नहीं की।",
  "daemon.draft_restore_unconfirmed.recovery": "इनपुट बॉक्स में मौजूद टेक्स्ट भेजने से पहले उसे जाँचें।",
  "daemon.draft_restore_unconfirmed.details": "ड्राफ़्ट अलग रखे जाने के दौरान सेशन में टाइप किया गया टेक्स्ट अब जैसे है वैसे इनपुट बॉक्स में जाएगा और संदेश दोबारा नहीं भेजा जाएगा।",
  "daemon.typing_held.summary": "{appName} के संदेश लिखते समय इस सेशन में टाइप किए गए टेक्स्ट का कुछ हिस्सा अभी {agent} तक नहीं पहुँचा है।",
  "daemon.typing_held.recovery": "सेशन में डायलॉग दिखे तो उसका जवाब दें।",
  "daemon.typing_held.details": "{agent} डायलॉग दिखा रहा है या इनपुट नहीं ले रहा है। वह दोबारा इनपुट लेने लगेगा तो रोका गया टेक्स्ट क्रम से टाइप किया जाएगा।",
  "daemon.typing_blocked.summary": "इस सेशन में लिखे संदेश का सिर्फ़ कुछ हिस्सा इनपुट बॉक्स तक पहुँचा। संदेश दोबारा नहीं भेजा जाएगा।",
  "daemon.typing_blocked.recovery": "प्रॉम्प्ट भेजने से पहले इनपुट बॉक्स जाँचें और संदेश का बचा हिस्सा हटाएँ।",
  "daemon.typing_blocked.details": "संदेश लिखे जाने के दौरान सेशन में टाइप किया गया टेक्स्ट आपके दोबारा टाइप करने पर छोड़ दिया जाता है, और उसके बाद आपका टाइप किया टेक्स्ट सीधे {agent} को जाता है। {appName} के दूसरे संदेश प्रॉम्प्ट भेजे जाने तक इंतज़ार करते हैं।",
  "daemon.terminal_input_lost.summary": "टाइप किया सारा टेक्स्ट लेने से पहले टर्मिनल का कनेक्शन टूट गया।",
  "daemon.terminal_input_lost.recovery": "आगे बढ़ने से पहले टर्मिनल की इनपुट लाइन जाँचें।",
  "daemon.terminal_input_lost.session.summary": "टाइप किया सारा टेक्स्ट लेने से पहले सेशन {session} के टर्मिनल का कनेक्शन टूट गया।",
  "daemon.terminal_input_lost.session.recovery": "आगे बढ़ने से पहले टर्मिनल की इनपुट लाइन जाँचें।",
