  "daemon.project_has_running_sessions": "इस प्रोजेक्ट में अभी सेशन चल रहे हैं या शुरू हो रहे हैं। चल रहे सेशन आर्काइव करें, या शुरू हो रहे सेशन के पूरा होने का इंतज़ार करें।",
  "daemon.process_shares_agent_console": "यह प्रोसेस एजेंट के अपने टर्मिनल में चल रहा है, इसलिए सेशन के साथ खत्म हो जाता है और चालू नहीं रखा जा सकता। इसे चालू रखने के लिए इसे अलग विंडो में शुरू करें।",
  "daemon.process_not_stopped": "{appName} द्वारा बंद करने की कोशिश के बाद भी यह प्रोसेस या इसके कुछ अधीन प्रोसेस चल रहे हैं। थोड़ी देर में दोबारा कोशिश करें।",
  "daemon.process_not_stopped.accessDenied": "{appName} के पास इस प्रोसेस या इसके कुछ अधीन प्रोसेस को बंद करने की अनुमति नहीं है, इसलिए वे अब भी चल रहे हैं। इन्हें बंद करने के लिए {appName} को उन्हीं अनुमतियों के साथ चलाएँ जो इन प्रोसेस के पास हैं।",
  "daemon.project_directory_shared": "यह फ़ोल्डर प्रोजेक्ट {project} के साथ शेयर है, इसलिए इसे {trash} में नहीं भेजा जा सकता। पहले वह प्रोजेक्ट हटाएँ, या फ़ोल्डर रखें।",
  "daemon.project_directory_shared.retryTrash": "इस फ़ोल्डर का दायरा प्रोजेक्ट {project} से मिलता है, इसलिए इसे {trash} में नहीं भेजा जा सकता। इस फ़ोल्डर को {trash} में भेजने से पहले इसके दायरे में आने वाला प्रोजेक्ट हटाना होगा।",
  "daemon.project_directory_protected": "यह आपका होम फ़ोल्डर या डिस्क का रूट है, या इसमें ऐप का अपना डेटा है, इसलिए इसे {trash} में नहीं भेजा जा सकता।",
  "daemon.project_directory_trash_failed": "फ़ोल्डर {trash} में नहीं भेजा जा सका, इसलिए प्रोजेक्ट रखा गया: {detail}",
  "daemon.project_directory_trash_failed.summary": "फ़ोल्डर {trash} में नहीं भेजा जा सका, इसलिए प्रोजेक्ट रखा गया।",
  "daemon.project_directory_trash_failed.unanswered": "फ़ोल्डर, आपके होम फ़ोल्डर या ऐप के डेटा फ़ोल्डर ने समय पर जवाब नहीं दिया, इसलिए फ़ोल्डर की जाँच नहीं हो सकी और प्रोजेक्ट रखा गया। वॉल्यूम के फिर जवाब देने पर दोबारा कोशिश करें, या फ़ोल्डर को {trash} में भेजे बिना प्रोजेक्ट हटाएँ।",
  "daemon.project_directory_trash_failed.unanswered.retryTrash": "फ़ोल्डर, आपके होम फ़ोल्डर या ऐप के डेटा फ़ोल्डर ने समय पर जवाब नहीं दिया, इसलिए फ़ोल्डर की जाँच नहीं हो सकी और प्रोजेक्ट रखा गया। वॉल्यूम के जवाब देने पर दोबारा कोशिश करें।",
  "daemon.project_directory_trash_failed.unanswered.summary": "फ़ोल्डर, आपके होम फ़ोल्डर या ऐप के डेटा फ़ोल्डर ने समय पर जवाब नहीं दिया, इसलिए फ़ोल्डर की जाँच नहीं हो सकी और प्रोजेक्ट रखा गया।",
  "daemon.project_directory_trash_failed.unanswered.retryTrash.summary": "फ़ोल्डर, आपके होम फ़ोल्डर या ऐप के डेटा फ़ोल्डर ने समय पर जवाब नहीं दिया, इसलिए फ़ोल्डर की जाँच नहीं हो सकी और प्रोजेक्ट रखा गया।",
