  "dialog.trust.behavior": "आपकी सहमति पर {appName} आपकी ओर से {agent} की भरोसे की पुष्टि स्वीकार करता है। एजेंट भरोसा दर्ज करता है और यहाँ फिर नहीं पूछता। यह अनुमति हर एजेंट के लिए भी सेव होती है, इसलिए इस प्रोजेक्ट की अगली भरोसे की पुष्टि आपसे पूछे बिना स्वीकार हो जाती है।",
