  "settings.closeIdleTerminals.label": "पैनल बंद करते समय निष्क्रिय टर्मिनल बंद करें",
  "settings.closeIdleTerminals.description.off": "इसे चालू करने पर, टर्मिनल पैनल बंद करने से उसके निष्क्रिय टर्मिनल बंद हो जाते हैं। जिन टर्मिनल में प्रोग्राम चल रहे हैं, वे खुले रहते हैं।",
  "settings.closeIdleTerminals.description.on": "टर्मिनल पैनल बंद करने से उसके निष्क्रिय टर्मिनल बंद हो जाते हैं। जिन टर्मिनल में प्रोग्राम चल रहे हैं, वे खुले रहते हैं।",
  "configuration.import.settings.consequence.closeIdleTerminals": "टर्मिनल पैनल बंद करने से उसके निष्क्रिय टर्मिनल बंद हो जाएंगे और प्रोग्राम चलाने वाले टर्मिनल खुले रहेंगे।",
  "settings.archiveCleanup.label": "जिन आर्काइव किए सेशन की बातचीत मिट गई है उन्हें अपने आप डिलीट करें",
  "settings.archiveCleanup.description.off": "चालू होने पर जब एजेंट किसी आर्काइव किए सेशन की बातचीत नहीं रखता, तो सेशन अपने आप डिलीट होता है। ऐप शुरू होने पर और फिर लगभग रोज़ आर्काइव किए सेशन जाँचे जाते हैं। पिन और लॉक किए सेशन रखे जाते हैं।",
  "settings.archiveCleanup.description.on": "जब एजेंट किसी आर्काइव किए सेशन की बातचीत नहीं रखता, तो सेशन अपने आप डिलीट होता है। ऐप शुरू होने पर और फिर लगभग रोज़ आर्काइव किए सेशन जाँचे जाते हैं। पिन और लॉक किए सेशन रखे जाते हैं।",
  "settings.sidebarOrder.label": "स्टेटस के हिसाब से साइडबार का क्रम रखें",
  "settings.sidebarOrder.description.off": "चालू होने पर सेशन और प्रोजेक्ट स्टेटस बदलने पर जगह बदलते हैं, ताकि आपका इंतज़ार कर रहे आइटम पिन किए आइटम के बाद पहले आएँ। जिन प्रोजेक्ट का कोई बिना आर्काइव किया सेशन नहीं है वे अंत में आते हैं।",
  "settings.sidebarOrder.description.on": "सेशन और प्रोजेक्ट स्टेटस बदलने पर जगह बदलते हैं, ताकि आपका इंतज़ार कर रहे आइटम पिन किए आइटम के बाद पहले आएँ। जिन प्रोजेक्ट का कोई बिना आर्काइव किया सेशन नहीं है वे अंत में आते हैं।",
  "settings.agentPermissions.lead": "चुनें कि सेशन आपसे पूछे बिना क्या कर सकते हैं और आपसे कैसे पूछते हैं।",
