  "settings.autoApproveSession.approvalDescription.on": "कोई सेशन आपसे पूछे बिना नए सेशन शुरू कर सकता है।",
  "settings.autoApproveResume.label": "फिर से शुरू करने के अनुरोध अपने आप मंज़ूर करें",
  "settings.autoApproveResume.approvalDescription.off": "चालू होने पर कोई सेशन आपसे पूछे बिना आर्काइव किए गए सेशन दोबारा खोल सकता है या बीच में रुके सेशन और मौजूदा बातचीत फिर से शुरू कर सकता है।",
  "settings.autoApproveResume.approvalDescription.on": "कोई सेशन आपसे पूछे बिना आर्काइव किए गए सेशन दोबारा खोल सकता है या बीच में रुके सेशन और मौजूदा बातचीत फिर से शुरू कर सकता है।",
