  "settings.autoSelect.description.on": "नया सेशन उस अकाउंट को इस्तेमाल करता है जिसकी साप्ताहिक सीमा सबसे पहले रीसेट होगी, ताकि रीसेट से पहले बचा इस्तेमाल बेकार न जाए।",
