  "settings.startQuotaWindows.helpText": "रीसेट हो चुकी इस्तेमाल की अवधि अकाउंट के अगले अनुरोध तक गिनना शुरू नहीं करती; तब तक उलटी गिनती नहीं दिखती और जितना देर इंतज़ार होता है, अगला रीसेट उतना देर से आता है। चालू होने पर इसे शुरू करने के लिए उस अकाउंट से एजेंट के सबसे सस्ते मॉडल पर एक छोटा अनुरोध भेजा जाता है।",
