  "settings.git.autoPull.label": "रिपॉज़िटरी अपने आप पुल करें",
  "settings.git.autoPull.description.off": "चालू होने पर प्रोजेक्ट की ब्रांच अपने अपस्ट्रीम से पीछे हो और फ़ास्ट-फ़ॉरवर्ड हो सकती हो तो पुल होती है। कुछ पुश नहीं होता और अपने कमिट वाली ब्रांच जैसी है वैसी रहती है।",
  "settings.git.autoPull.description.on": "प्रोजेक्ट की ब्रांच अपने अपस्ट्रीम से पीछे हो और फ़ास्ट-फ़ॉरवर्ड हो सकती हो तो पुल होती है। कुछ पुश नहीं होता और अपने कमिट वाली ब्रांच जैसी है वैसी रहती है।",
