  "settings.trusted.removeMessage": "इस फ़ोल्डर के अंदर प्रोजेक्ट की अगली भरोसे की पुष्टि फिर आपसे पूछेगी, जब तक प्रोजेक्ट की अनुमति या दूसरा भरोसेमंद फ़ोल्डर उन्हें शामिल न करे। मौजूदा प्रोजेक्ट अनुमतियाँ, चल रहे सेशन और हर एजेंट में पहले से दर्ज भरोसा रहते हैं।",
  "settings.trusted.removeLabel": "भरोसेमंद फ़ोल्डर {path} हटाएँ",
  "settings.accounts.description": "अकाउंट एजेंट की नाम दी गई कॉन्फ़िग डायरेक्टरी है: वह डायरेक्टरी जिसमें एजेंट लॉगिन और बातचीत की हिस्ट्री रखता है। अकाउंट इस्तेमाल करने के लिए एजेंट आपके {pathVar} में होना चाहिए।",
